//TODO autorange and interpolate with spectral weight
//TODO load from the saved files
int computeQuantities(int numberOfSites, bool toSave, GreensFunctionTest GF, const std::vector<std::shared_ptr<SelfEnergyBase<SelfEnergyMatrix>>>& SEs,numType mu)
{
    auto GFunc = GF.m_gfunc;
    int ret  = 0;
    std::string filenameBase = std::string("Sites") + std::to_string(numberOfSites);
    std::string extenstion = ".txt";
    //Current Calc - Deprecated so not tested
    //DivCurrentCalc
    {// TODO Tests with perturbative corrections to the current
        DivCurrentCalc::Parameters p;
        p.numberOfIntegrationPoints = 1000000;
        p.startE = mu-30*kb*T;
        p.endE = mu+1+30*kb*T;
        DivCurrentCalc Calc(p);
        int count = 0;

        for (auto& se : SEs)
        {
            count++;
            std::string filename = filenameBase + std::string("Current") + std::to_string(count) + extenstion;
            if (toSave)
                logger(filename,false);

            Calc.setGreensFunction(GFunc,{se});
            Eigen::VectorXd curr;
            Calc.getAtE(mu+0.5,curr);
            if (toSave)
                logger(filename,true).logAccurate("CurrAt0.5",curr);
            else
            {
                auto map = Eigen::Map<Eigen::Matrix<numType, 20, 1> >(Tabulatedcurrentat0p5[count-1]);
                Eigen::VectorXd currExpt(map);
                ret += expectNear(currExpt,curr,matrixNear,__PRETTY_FUNCTION__,"Curr Expt at 0.5");
            }
            auto curr2 = Calc.getAtE(std::vector<numType>({0.5}));
            ret += expect(1ul,curr2.size(),__PRETTY_FUNCTION__,"currLength");
            ret += expect(curr2[0],curr,__PRETTY_FUNCTION__,"Vectorised curr value");
            auto curr3 = Calc.get();
            if (toSave)
                logger(filename,true).logAccurate("Currtotal",curr3);
            else
            {
                auto map = Eigen::Map<Eigen::Matrix<numType, 20, 1> >(Tabulatedcurrent[count-1]);
                Eigen::VectorXd currExpt(map);
                ret += expectNear(currExpt,curr3,matrixNear,__PRETTY_FUNCTION__,"Curr Expt");
            }
            // TransmissionFunc trFunc;
            // trFunc.setGreensFunction(GFunc);

            // std::vector<complexType> poles;
            // GFunc->getEstimateForDivergencesOfGr(0,poles);

            // complexType transmission;
            // SpectralWeightedIntegral<false>(p.startE,p.endE,p.numberOfIntegrationPoints,transmission,poles,[&](numType E, complexType& dest){dest = trFunc.getTransmissionAtEBetween(E,SEs[0],SEs[2]);},[](){return 0;});
            // transmission/=(2*M_PI);

            // logger().log("Transmission",transmission);
            logger().log("Curr3", curr3.sum());

            ret += expect(true,Calc.isConstant(),__PRETTY_FUNCTION__,"isConstant");
        }
    }
    //electron density calc
    {
        ElectronDensityCalc::Parameters p;
        p.numberOfIntegrationPoints = 100000;
        p.startE = mu-30*kb*T;
        p.endE = mu+1+30*kb*T;
        ElectronDensityCalc Calc(p);
        std::string filename = filenameBase + std::string("ElectronDensityCalc") + extenstion;

        if (toSave)
            logger(filename,false);

        Calc.setGreensFunction(GFunc);
        auto Gn1 = Calc.getGn(false);
        if (toSave)
            logger(filename,true).logAccurate("Gn1",Gn1);
        else
        {
            auto map = Eigen::Map<Eigen::Matrix<complexType, 20, 20,Eigen::RowMajor> >((complexType*)TabulatedGn); // horrible bithacking
            ComplexSelfAdjointMatrix Gn1Expt(Eigen::MatrixXcd(map),quantityCalcTestBasis,enums::SpinSymmetry::RHF);
            ret += expectNear(Gn1Expt,Gn1,makeMatrixNearTol(Gn1,1e-12),__PRETTY_FUNCTION__,"Gn1 Expt");
            if (ret)
                logger().log("Gn1Expt error", (Gn1-Gn1Expt).norm());
        }
        auto Gn2 = Calc.getGn(true);
        ret += expect(Gn1,Gn2,__PRETTY_FUNCTION__,"Check Perturb");

        auto nR = Calc.getnR();
        ret += expectNear(Eigen::VectorXd(Gn1.diagonal().real()),nR,matrixNear,__PRETTY_FUNCTION__,"Check Diagonal");

        nR = Calc.getnR(quantityCalcTestBasis);
        ret += expectNear(Eigen::VectorXd(Gn1.diagonal().real()),nR,matrixNear,__PRETTY_FUNCTION__,"Check DiagonalBasisChange");

        Eigen::VectorXcd nSExpt(numberOfSites*4);
        for(long i = 0; i < numberOfSites;i++)
        {
            nSExpt(4*i) = Gn1(2*i,2*i);
            nSExpt(4*i+1) = Gn1(2*i,2*i+1);
            nSExpt(4*i+2) = Gn1(2*i+1,2*i);
            nSExpt(4*i+3) = Gn1(2*i+1,2*i+1);
        }
        auto nS = Calc.getnS();
        ret += expect(nSExpt,nS,__PRETTY_FUNCTION__,"nS");

        auto NEr = Calc.getnEr(mu+0.5);
        if (toSave)
            logger(filename,true).logAccurate("getnEr0.5",NEr);
        else
        {
            auto map = Eigen::Map<Eigen::Matrix<numType, 20, 1> >(TabulatedNeR0p5); // horrible bithacking
            Eigen::VectorXd NErExpt(map);
            ret += expectNear(NErExpt,NEr,matrixNear,__PRETTY_FUNCTION__,"NEr Expt");
        }
        auto NEr2 = Calc.getnEr(mu+0.5,quantityCalcTestBasis);
        ret += expect(NEr,NEr2,__PRETTY_FUNCTION__,"BasisChangeTest");

        auto NEr3 = Calc.getnEr(std::vector<numType>({mu+0.5}));
        auto NEr4 = Calc.getnEr(std::vector<numType>({mu+0.5}),quantityCalcTestBasis);

        ret += expect(NEr,NEr3[0],__PRETTY_FUNCTION__,"ner3");
        ret += expect(NEr,NEr4[0],__PRETTY_FUNCTION__,"ner4");
    }
    //SpectralFunction calc
    {
        SpectralFunction::Parameters p;
        p.numberOfIntegrationPoints = 1000000;
        p.startE = mu-30*kb*T;
        p.endE = mu+1+30*kb*T;
        SpectralFunction Calc(p);
        std::string filename = filenameBase + std::string("AR") + extenstion;

        if (toSave)
            logger(filename,false);

        Calc.setGreensFunction(GFunc);
        auto AR = Calc.getAR();
        if (toSave)
            logger(filename,true).logAccurate("AR",AR);
        else
        {
            Eigen::VectorXd expt(AR.rows());
            expt.setOnes();
            expt *= 2*M_PI;
            ret += expectNear(expt,AR, (bool (*)(const Eigen::VectorXd& , const Eigen::VectorXd& ))[](const Eigen::VectorXd& a, const Eigen::VectorXd& b){return (a-b).norm()<1e-10;},__PRETTY_FUNCTION__,"Check AR integral");
        }

        // auto AR2 = Calc.getAR(quantityCalcTestBasis);
        // ret += expect(AR,AR2,__PRETTY_FUNCTION__,"ARBasisChangeTest");

        auto AEr = Calc.getAEr(mu+0.5);
        if (toSave)
            logger(filename,true).logAccurate("getAEr0.5",AEr);
        else
        {
            auto map = Eigen::Map<Eigen::Matrix<numType, 20, 1> >(TabulatedAr[1]);
            Eigen::VectorXd AErExpt(map);
            ret += expectNear(AErExpt,AEr,matrixNear,__PRETTY_FUNCTION__,"AEr Expt");
        }
        auto AEr2 = Calc.getAEr(mu+0.5,quantityCalcTestBasis);
        ret += expect(AEr,AEr2,__PRETTY_FUNCTION__,"BasisChangeTest");

        auto AEr3 = Calc.getAEr(std::vector<numType>({mu+0.5}));
        auto AEr4 = Calc.getAEr(std::vector<numType>({mu+0.5}),quantityCalcTestBasis);

        ret += expect(AEr,AEr3[0],__PRETTY_FUNCTION__,"AEr3");
        ret += expect(AEr,AEr4[0],__PRETTY_FUNCTION__,"AEr4");
    }
    //OperatorExpectationValue - Unused so not Implemented
    //TransmissionFunc - Basically Unused so not Implemented
    //Thermal Energy
    {
        ThermalEnergy::Parameters p;
        p.numberOfIntegrationPoints = 100000;
        p.startE = mu-30*kb*T;
        p.endE = mu+1+30*kb*T;
        p.extraEnergy = 10;
        ThermalEnergy Calc(p);
        std::string filename = filenameBase + std::string("ThermalEnergy") + extenstion;
        Calc.setGreensFunction(GFunc);

        if (toSave)
            logger(filename,false);
        numType energy = Calc.getEnergy();
        if (toSave)
            logger(filename,true).logAccurate("ThermalEnergy",energy);
        else
        {
            ret += expectNear(TabulatedThermalEnergy[0],energy,__PRETTY_FUNCTION__,"ThermalEnergy Expt");
        }
        numType energy2 = Calc.getEnergy(quantityCalcTestBasis);
        ret += expect(energy,energy2,__PRETTY_FUNCTION__,"ThermalEnergyProjector");
        auto energies = Calc.getAtE(mu+0.5);
        if (toSave)
            logger(filename,true).logAccurate("ThermalEnergyAt0.5",energies);
        else
        {
            ret += expectNear(TabulatedThermalEnergy[1],energies,__PRETTY_FUNCTION__,"ThermalEnergyat0.5 Expt");
        }
        auto energies2 = Calc.getAtE(mu+0.5,quantityCalcTestBasis);
        ret += expect(energies,energies2,__PRETTY_FUNCTION__,"BasisChangeThermalEnergy");
        auto energies3 = Calc.getAtE(std::vector<numType>({mu+0.5}),quantityCalcTestBasis);
        ret += expect(energies,energies3[0],__PRETTY_FUNCTION__,"BasisChangeThermalEnergy");
    }
    return ret;
}

static int testCyclicBoundaryConditions(int numberOfSites, bool restrictedCalc, numType mu, std::string workingBasis,
                                 GreensFunction::integratorType integType)
{// This will fail at runtime due to no conversion from orthBasis to quantityCalcBasis
    //transform = L^{i}_{\mu} stored as L_{i\mu}
    //c^\nu \ket{e_\nu} = c^i L^{\nu}_{i} {e_\nu}
    //h_{\bar{\mu}\nu} = L^{\bar{i}}_{\bar{\mu}} h_{\bar{i}j} L^{j}_{\nu}
    //h_{\bar{\mu}\nu} = L^\dagger h L
    //S_{\bar{\mu}\nu} = \bra{e_\mu}\ket{e_\nu} = L^{\bar{i}}_{\bar{\mu}}L^{i}_{\nu} = L^\dagger L

    // GR_{ij} = L^{\bar{\kappa}}_{\bar{i}}S_{\bar{\kappa},\mu}GR^{\mu}_{\nu}L^{\nu}{j}
    // GR_{ij} = L^{\bar{\kappa}}_{\bar{i}}L^{\bar{k}}_{\bar{\kappa}}L^{k}_{\mu}GR^{\mu}_{\nu}L^{\nu}_{j}
    // GR_{ij} = L^{i}_{\mu}GR^{\mu}_{\nu}L^{\nu}_{j}
    // GR_{ij} = L GR L^{-1}

    logger().log(std::string("Running ") +std::string(__PRETTY_FUNCTION__) + std::string("with ") + std::to_string(numberOfSites) + " sites and restrictedCalc=" + std::to_string(restrictedCalc));
    int ret = 0;
    ComplexSelfAdjointSparseMatrix Ham = constructPeriodicHamilonian(numberOfSites,quantityCalcTestBasis);
    ComplexSelfAdjointSparseMatrix HamTransformed;
    Ham.toBasisC(HamTransformed,workingBasis);


    //Make self energy
    SimpleLeadSelfEnergy<SelfEnergyMatrix>::Parameters SEparams;

    SEparams.alpha1 = 1;
    SEparams.t = LeadGamma;
    SEparams.mu = mu;
    SEparams.couplingPoints.resize(numberOfSites*2,numberOfSites*2,quantityCalcTestBasis,enums::SpinSymmetry::RHF); //This enum isnt great since we want to construct in the spatial basis
    SEparams.couplingPoints.setZero();
    SEparams.couplingPoints(0,0) = 1;
    SEparams.couplingPoints(1,1) = 1;
    SEparams.couplingPoints.toBasisC(SEparams.couplingPoints,workingBasis+BasisManager::Alpha_Block);

    SEparams.magnetisationDir.setZero();
    SEparams.upSpin = true;
    SEparams.MatrixDimension = numberOfSites*2;

    auto upSpinSEL = std::make_shared<SimpleLeadSelfEnergy<SelfEnergyMatrix>>(SEparams);
    SEparams.upSpin = false;
    auto downSpinSEL = std::make_shared<SimpleLeadSelfEnergy<SelfEnergyMatrix>>(SEparams);

    SEparams.mu = mu+1;
    SEparams.upSpin = true;
    SEparams.couplingPoints.resize(numberOfSites*2,numberOfSites*2,quantityCalcTestBasis,enums::SpinSymmetry::RHF);
    SEparams.couplingPoints.setZero();
    SEparams.couplingPoints(numberOfSites*2-2,numberOfSites*2-2) = 1;
    SEparams.couplingPoints.toBasisC(SEparams.couplingPoints,workingBasis+BasisManager::Alpha_Block);

    auto upSpinSER = std::make_shared<SimpleLeadSelfEnergy<SelfEnergyMatrix>>(SEparams);
    SEparams.upSpin = false;
    auto downSpinSER = std::make_shared<SimpleLeadSelfEnergy<SelfEnergyMatrix>>(SEparams);

    GreensFunctionTest GF;
    GF.setup(HamTransformed,integType);

    GF.m_gfunc->setSelfEnergies({upSpinSEL,downSpinSEL,upSpinSER,downSpinSER});
    GF.m_gfunc->setRestrictedCalculation(restrictedCalc);
    ret += computeQuantities(numberOfSites,false,GF, GF.m_gfunc->getSelfEnergies(),mu);
    return ret;
}


int quantitycalcTests(int argc, char** argv)
{
    int ret = 0;
    BasisManager::getInstance().addOrthogonalBasis(quantityCalcTestBasis,20);
    ret += testCyclicBoundaryConditions(10,true,0,quantityCalcTestBasis,GreensFunction::integratorType::autoDetect);
    BasisManager::deleteBasis(quantityCalcTestBasis);
    return ret > 0 ? -1 : 0;
}
